{
  "events": [
    {
      "id": "E1",
      "title": "珀莱雅举办2026创新科技大会（PSTC 2026），发布《中国系统性护肤研究与产业实践白皮书》及红宝石面霜4.0、源力精华4.0",
      "date": "2026-08-25",
      "category": "research",
      "sourceIds": ["C1"],
      "quote": "8月25日，以\"科技向新，为美前行\"为主题的珀莱雅2026创新科技大会（PSTC 2026 — PROYA FORWARD）在上海举行。大会上，珀莱雅联合上海日用化学品行业协会发布《中国系统性护肤研究与产业实践白皮书》，推出红宝石面霜4.0、源力精华4.0两大核心产品升级",
      "summary": "珀莱雅于2026年8月25日召开PSTC 2026大会，正式发布行业首份系统性护肤白皮书，提出CRMVP五维循证模型；同步升级红宝石面霜4.0（强调'皮骨双修'）与源力精华4.0（聚焦基底膜ECM修复），并启动'极境挑战'真实场景测试。该活动属品牌科技能力体系化输出，非新品上市或销售落地动作。"
    },
    {
      "id": "E2",
      "title": "珀莱雅联合浙江大学将AI技术引入活性成分高效筛选，并与上海市皮肤病医院共建临床科创实验室",
      "date": "2026-09-01",
      "category": "research",
      "sourceIds": ["C2"],
      "quote": "依托于杭州龙坞、上海及欧洲三大研发中心，珀莱雅今年联合浙江大学研究团队将AI技术引入活性成分的高效筛选；还与上海市皮肤病医院共建临床科创实验室，让基础探索与临床一线的真实需求深度咬合。",
      "summary": "珀莱雅在2026年深化产学研医协同，明确披露与浙江大学合作应用AI进行活性成分筛选，以及与上海市皮肤病医院共建临床科创实验室。该动作属研发能力建设，未涉及具体原料采购、代工订单或商业化产品交付。"
    },
    {
      "id": "E3",
      "title": "第三方测评显示珀莱雅新款修颜防晒乳通过《化妆品安全技术规范》新增光稳定性强制检测，且为唯一实现'防晒+修色+舒缓'三重备案功效宣称的产品",
      "date": "2026-10-22",
      "category": "product",
      "sourceIds": ["C3"],
      "quote": "2026年《化妆品安全技术规范》新增‘防晒剂光稳定性强制检测项’，5款产品中仅珀莱雅与理肤泉通过全周期光照衰减测试（120分钟内SPF下降＜15%）。而珀莱雅同步通过广东省微生物分析检测中心‘人体斑贴试验’（n=300，刺激性0例），是本次测评中唯一实现‘防晒+修色+舒缓’三重备案功效宣称的产品。",
      "summary": "2026年10月22日发布的第三方横向测评指出，珀莱雅新款修颜防晒乳满足新规光稳定性要求，并完成防晒、修色、舒缓三重功效备案；其微粒化氧化锌+乙基己基三嗪酮体系及0.8%烟酰胺+0.3%云母微珠配方被实测验证。该信息源于终端在售批次检测，不构成公司主动披露的经营成果。"
    }
  ],
  "judgments": [
    {
      "title": "红宝石/源力4.0升级与PSTC大会存在财报印证缺口",
      "text": "财报P11仅提及红宝石微珠精华、双抗次抛等上半年已上新产品，未列示红宝石面霜4.0与源力精华4.0；C1中'8月25日发布'明确晚于半年报截止日（2026-06-30），故该升级属下半年研发动作，若误读为上半年收入贡献则违背'不得把近期合作、产品发布写成上半年已实现收入'前提。需验证其是否进入Q3量产及渠道铺货节奏。",
      "financialEvidenceIds": ["P11"],
      "sourceIds": ["C1"]
    },
    {
      "title": "AI用于活性成分筛选尚未反映在研发投入变化中",
      "text": "财报P23显示2026年上半年研发费用率微降至1.85%，P23原文称'研发费用同比增加440.37万元'，增幅4.63%低于营收增速（0.24%），提示投入强度未显著提升；C2所述AI筛选属方法论升级，但若无对应研发费用结构披露（如算法服务采购、算力支出），则其实际资源投入规模仍需验证。",
      "financialEvidenceIds": ["P23"],
      "sourceIds": ["C2"]
    },
    {
      "title": "修颜防晒乳三重功效备案可能预示原料端新需求方向",
      "text": "C3指出该产品为测评中唯一完成'防晒+修色+舒缓'三重备案的产品，其配方含微粒化氧化锌（80–120nm）、乙基己基三嗪酮、烟酰胺及云母微珠；财报P10未单列防晒品类收入，P23亦未提及相关原料采购变动，故该备案能力若转化为批量生产，可能对具备纳米氧化锌稳定分散、高纯度烟酰胺载体及云母表面改性技术的原料商构成潜在适配信号，但仍需验证其是否已进入主力SKU或渠道主推序列。",
      "financialEvidenceIds": ["P10", "P23"],
      "sourceIds": ["C3"]
    }
  ],
  "actions": [
    {
      "audience": "原料商",
      "text": "建议关注微粒化氧化锌（80–120nm）、乙基己基三嗪酮复配体系及0.8%烟酰胺稳定载体的技术适配性，评估是否具备满足防晒剂光稳定性强制检测所需的工艺冗余与备案支持文档。",
      "financialEvidenceIds": ["P10", "P23"],
      "sourceIds": ["C3"],
      "verifyWith": "纳米氧化锌的粒径分布报告、乙基己基三嗪酮的相容性测试数据、烟酰胺在乳霜体系中的48小时降解率检测记录及化妆品功效评价指导原则备案服务资质"
    },
    {
      "audience": "代工厂",
      "text": "建议梳理具备防晒类妆字号产品灌装洁净等级（D级及以上）、UVA-PF实验室协同检测接口及人体斑贴试验项目对接经验的服务能力清单。",
      "financialEvidenceIds": ["P11", "P23"],
      "sourceIds": ["C3"],
      "verifyWith": "GMP证书洁净级别附页、与第三方检测机构（如广东省微生物分析检测中心）签署的检测协作协议、近一年完成的防晒类产品人体安全性评价项目案例"
    },
    {
      "audience": "品牌方",
      "text": "建议研判珀莱雅将CRMVP五维模型与极端环境实证结合的传播策略，评估其对自有产品功效宣称体系的参考价值，尤其关注从'单项技术突破'转向'系统解决方案'所需的消费者教育成本。",
      "financialEvidenceIds": ["P11"],
      "sourceIds": ["C1"],
      "verifyWith": "自有品牌近三年功效宣称相关行政处罚记录、消费者调研中对'系统性护肤'概念的认知率与信任度数据、已完成的极端环境（高温/高湿/强紫外线）下产品稳定性实测报告"
    }
  ]
}
